# First, we need to write a function to check if a number is prime.
# Then we'll write a function to find the largest prime factor of a given number.

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def largest_prime_factor(n):
    # Keep dividing n by 2 to remove all even factors
    while n % 2 == 0:
        n = n // 2
    # Check for odd factors from 3 onwards
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            n = n // i
    # If n becomes a prime number greater than 2
    if n > 2:
        return n
    # If n is 1, it means we have already removed all factors
    return 2

# Let's find the largest prime factor of 3328
number = 3328
largest_prime = largest_prime_factor(number)
print(largest_prime)
